    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def get_pos(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for kx, ky in (("x", "y"), ("col", "row"), ("cx", "cy"), ("px", "py")):
                if kx in obj and ky in obj:
                    return [obj[kx], obj[ky]]
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            return [obj[0], obj[1]]
        return None

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign(v):
        return (v > 0) - (v < 0)

    def in_bounds(x, y, w, h):
        return 0 <= x < w and 0 <= y < h

    def cell(grid, x, y):
        if not grid:
            return None
        if y < 0 or y >= len(grid):
            return None
        row = grid[y]
        if x < 0 or x >= len(row):
            return None
        return row[x]

    def is_blocked(v):
        if v is None:
            return False
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)):
            return v != 0
        if isinstance(v, str):
            s = v.lower()
            return s in ("wall", "blocked", "#", "x", "true", "obstacle")
        if isinstance(v, dict):
            for k in ("blocked", "wall", "obstacle", "solid"):
                if v.get(k):
                    return True
        return False

    def extract_positions(value):
        out = []
        if value is None:
            return out
        if isinstance(value, dict):
            if "x" in value and "y" in value:
                out.append([value["x"], value["y"]])
            for k in ("positions", "cells", "items", "agents", "enemies", "opponents", "resources", "targets", "territory"):
                if k in value:
                    out.extend(extract_positions(value.get(k)))
        elif isinstance(value, (list, tuple)):
            for item in value:
                p = get_pos(item)
                if p is not None:
                    out.append(p)
                else:
                    out.extend(extract_positions(item))
        return out

    obs = observation if isinstance(observation, dict) else {}
    me = get_pos(obs.get("self")) or get_pos(obs.get("agent")) or get_pos(obs.get("player")) or get_pos(obs.get("position"))
    if me is None:
        me = get_pos(obs.get("my_pos")) or get_pos(obs.get("me")) or [0, 0]

    grid = obs.get("grid") or obs.get("board") or obs.get("map")
    width = obs.get("width")
    height = obs.get("height")
    if grid and (width is None or height is None):
        try:
            height = len(grid)
            width = len(grid[0]) if height else 0
        except Exception:
            width = width or 0
            height = height or 0

    resources = extract_positions(obs.get("resources") or obs.get("resource_nodes") or obs.get("food") or obs.get("targets"))
    enemies = extract_positions(obs.get("enemies") or obs.get("opponents") or obs.get("threats") or obs.get("pursuers"))
    allies = extract_positions(obs.get("allies") or obs.get("teammates") or obs.get("friends"))

    terr = obs.get("territory") or obs.get("ownership") or obs.get("control")
    known = obs.get("explored") or obs.get("seen")

    game_type = str(obs.get("game_type") or obs.get("mode") or obs.get("scenario") or "").lower()

    candidates = []
    legal = obs.get("legal_moves") or obs.get("moves") or obs.get("action_mask")
    if isinstance(legal, (list, tuple)) and len(legal) >= 9:
        idx = 0
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                ok = legal[idx]
                idx += 1
                if ok:
                    candidates.append([dx, dy])
    if not candidates:
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                candidates.append([dx, dy])

