    is_resource = ("resource" in game_type) or (len(resources) > 0 and len(enemies) <= len(resources) + 2)
    is_pursuit = ("pursuit" in game_type) or ("evasion" in game_type) or (len(enemies) > 0 and len(resources) == 0)
    is_territory = ("territory" in game_type) or ("control" in game_type) or terr is not None

    best = None
    best_score = None

    for dx, dy in candidates:
        nx = me[0] + dx
        ny = me[1] + dy
        if width is not None and height is not None and width > 0 and height > 0:
            if not in_bounds(nx, ny, width, height):
                continue
        if grid is not None and width and height:
            c = cell(grid, nx, ny)
            if is_blocked(c):
                continue

        score = 0.0

        # General: prefer movement over staying unless justified
        if dx == 0 and dy == 0:
            score -= 0.2

        # Avoid adjacent enemies
        if enemies:
            dmin = min(manhattan([nx, ny], e) for e in enemies if e is not None)
            score += dmin * 2.0
            if dmin <= 1:
                score -= 8.0
            elif dmin == 2:
                score -= 2.0

        if is_resource and resources:
            dmin = min(manhattan([nx, ny], r) for r in resources if r is not None)
            score += 10.0 / (1.0 + dmin)
            # prefer reducing distance to closest resource
            curd = min(manhattan(me, r) for r in resources if r is not None)
            score += (curd - dmin) * 1.5

        elif is_pursuit:
            # maximize distance from threats; if no threats, drift to center/open space
            if width and height:
                cx, cy = width // 2, height // 2
                score -= 0.05 * manhattan([nx, ny], [cx, cy])
            if enemies:
                dmin = min(manhattan([nx, ny], e) for e in enemies if e is not None)
                score += dmin * 3.0
                if dmin <= 2:
                    score += 4.0

        elif is_territory:
            # Prefer frontier/unowned cells
            if grid is not None and width and height:
                here = cell(grid, nx, ny)
                if isinstance(here, str):
                    hs = here.lower()
                    if hs in ("neutral", "unowned", "empty", ".", "0"):
                        score += 5.0
                elif isinstance(here, (int, float)) and here == 0:
                    score += 4.0
            # Prefer moving outward from current position
            if width and height:
                score += abs(nx - width / 2.0) * 0.1 + abs(ny - height / 2.0) * 0.1

        else:
            # fallback heuristic: move toward resources, else away from enemies, else center
            if resources:
                dmin = min(manhattan([nx, ny], r) for r in resources if r is not None)
                score += 4.0 / (1.0 + dmin)
            if enemies:
                dmin = min(manhattan([nx, ny], e) for e in enemies if e is not None)
                score += 1.5 * dmin

        # If known/explored map exists, prefer unknown frontier in territory-like tasks
        if known is not None and isinstance(known, (list, tuple)):
            try:
                kv = cell(known, nx, ny)
                if kv is False or kv == 0 or kv is None:
                    score += 1.0
            except Exception:
                pass

        # Tie-break: deterministic directional preference
        score += dx * 0.001 + dy * 0.0001

        if best_score is None or score > best_score:
            best_score = score
            best = [dx, dy]

    if best is None:
        best = [0, 0]

    best[0] = clamp(best[0])
    best[1] = clamp(best[1])
    return best

